Actionscript.script:
onClipEvent (enterFrame)
{
    if (Key.isDown(38))
    {
        this._y = this._y - 20;
    } // end if
    if (Key.isDown(40))
    {
        this._y = this._y + 20;
    } // end if
}

onClipEvent (enterFrame)
{
    if (Key.isDown(38))
    {
        this._y = this._y - 20;
    } // end if
    if (Key.isDown(40))
    {
        this._y = this._y + 20;
    } // end if
}
